#include <algorithm>
#include <functional>
#include <string>
#include <vector>

struct Player
{
    std::string name{};
    int score{};
    int age{};
};

void sortByScore(std::vector<Player>& players)
{
    std::ranges::sort(players, std::greater{}, &Player::score);
}

std::string youngest(const std::vector<Player>& players)
{
    const auto it{ std::ranges::min_element(players, {}, &Player::age) };
    return it == players.end() ? "" : it->name;
}

unitTests:
std::vector<Player> team() { return { { "Ann", 50, 31 }, { "Bo", 90, 19 }, { "Cy", 70, 44 } }; }
TEST("sortByScore") { auto t{ team() }; sortByScore(t); CHECK_EQ(t[0].name, "Bo"); CHECK_EQ(t[1].name, "Cy"); CHECK_EQ(t[2].name, "Ann"); }
TEST("youngest") { CHECK_EQ(youngest(team()), "Bo"); CHECK_EQ(youngest({}), ""); }

